    # For a sequence a, we want to find max_{S valid} |sum_{i in S} a_i|.
    # A set S = {t_1, ..., t_k} is valid if t_{i+1} - t_i <= 2.
    # This means for every j from 1 to k-1, t_{j+1} - t_j is 1 or 2.

    def max_sum(a):
        n = len(a)
        # dp_pos[i] = max sum of a valid subsequence ending at index i
        # dp_neg[i] = min sum of a valid subsequence ending at index i
