        dp_neg = [0] * (n + 1)
        for i in range(1, n + 1):
            dp_pos[i] = a[i-1]
            dp_neg[i] = a[i-1]
            if i > 1:
                dp_pos[i] = max(dp_pos[i], dp_pos[i-1] + a[i-1])
